<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{adminApi}from'../api';import{ApiError,type Channel}from'@leadnews/shared';import{ElMessage,ElMessageBox}from'element-plus';const rows=ref<Channel[]>([]),dialog=ref(false),editing=ref<number>(),form=reactive<Channel>({name:'',description:'',status:'ENABLED',ord:0});async function load(){rows.value=await adminApi.channels()}function open(c?:Channel){editing.value=c?.id;Object.assign(form,c||{name:'',description:'',status:'ENABLED',ord:0});dialog.value=true}async function save(){try{editing.value?await adminApi.updateChannel(editing.value,form):await adminApi.createChannel(form);dialog.value=false;ElMessage.success('频道已保存');await load()}catch(e){ElMessage.error(e instanceof ApiError?e.message:'保存失败')}}async function toggle(c:Channel){if(!c.id)return;try{await adminApi.status(c.id,c.status==='ENABLED'?'DISABLED':'ENABLED');await load()}catch(e:any){ElMessage.error(e.message)}}async function remove(c:Channel){if(!c.id)return;await ElMessageBox.confirm(`删除频道“${c.name}”？`);try{await adminApi.deleteChannel(c.id);await load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load)</script><template><section class="panel"><div class="toolbar"><h1 style="flex:1">频道管理</h1><el-button type="primary" @click="open()">新建频道</el-button></div><el-table :data="rows"><el-table-column prop="name" label="名称"/><el-table-column prop="description" label="说明"/><el-table-column prop="ord" label="排序" width="90"/><el-table-column prop="status" label="状态" width="110"/><el-table-column width="230"><template #default="{row}"><el-button text @click="open(row)">编辑</el-button><el-button text @click="toggle(row)">{{row.status==='ENABLED'?'停用':'启用'}}</el-button><el-button text type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" :title="editing?'编辑频道':'新建频道'" width="min(520px,90vw)"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.ord" :min="0"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
